            if grid[r][c] != bg:
                positions.setdefault(grid[r][c], []).append((r, c))

    for color, pts in positions.items():
        if len(pts) < 2:
            continue
        # Find a pair of same-colored cells sharing a diagonal direction.
        pairs = []
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if abs(dr) == abs(dc) and dr != 0:
                    pairs.append((r1, c1, r2, c2))
        if not pairs:
            continue

        # Extend the most aligned pair away from its later endpoint.
        r1, c1, r2, c2 = pairs[-1]
        dr = 1 if r2 > r1 else -1
        dc = 1 if c2 > c1 else -1
        r, c = r2 + dr, c2 + dc
        while 0 <= r < h and 0 <= c < w:
            if grid[r][c] != bg:
                break
            out[r][c] = color
            r += dr
            c += dc
    return out
