def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = grid[0][0]
    colors = {v for row in grid for v in row if v != bg}

    for color in colors:
        pts = [(r, c) for r in range(h) for c in range(w)
               if grid[r][c] == color]
        # A repeated color on a diagonal defines a diagonal ray.
        found = False
        for i, (r1, c1) in enumerate(pts):
            for r2, c2 in pts[i + 1:]:
                dr, dc = r2 - r1, c2 - c1
                if dr and abs(dr) == abs(dc):
                    # Continue the line from both endpoints; this also
                    # handles a sequence with more than two matching cells.
                    sr = 1 if dr > 0 else -1
                    sc = 1 if dc > 0 else -1
                    for r, c, step in ((r1, c1, -1), (r2, c2, 1)):
                        rr, cc = r + step * sr, c + step * sc
                        while 0 <= rr < h and 0 <= cc < w:
                            if grid[rr][cc] != bg:
                                break
                            out[rr][cc] = color
                            rr += step * sr
                            cc += step * sc
                    found = True
                    break
            if found:
                break
    return out
